def crear_perfiles_existentes(apps, schema_editor):
    Usuario = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    PerfilUsuario = apps.get_model("tallermami", "PerfilUsuario")
    Cliente = apps.get_model("tallermami", "Cliente")
    Trabajador = apps.get_model("tallermami", "Trabajador")
    db_alias = schema_editor.connection.alias

    for usuario in Usuario.objects.using(db_alias).all().iterator():
        grupos = {
            nombre.casefold()
            for nombre in usuario.groups.values_list("name", flat=True)
        }
        cliente = Cliente.objects.using(db_alias).filter(
            usuario_id=usuario.pk
        ).first()
        trabajador = Trabajador.objects.using(db_alias).filter(
            usuario_id=usuario.pk
        ).first()

        if "secretario" in grupos:
            rol = "secretario"
        elif "jefe de taller" in grupos or usuario.is_superuser:
            rol = "jefe_taller"
        elif trabajador:
            rol = "mecanico"
        else:
            rol = "cliente"

        telefono = (
            trabajador.telefono
            if trabajador and trabajador.telefono
            else cliente.telefono
            if cliente
            else ""
        )
        PerfilUsuario.objects.using(db_alias).create(
            id_usuario_id=usuario.pk,
            telefono=telefono,
            rol=rol,
        )


